# -*- coding: utf-8 -*-
"""
Text2Manim DSL 验证器模块

提供 DSL 的语义验证和完整性检查。

Author: Text2Manim Team
Date: 2024-12
"""

import sys
from typing import Dict, List, Optional, Set, Tuple
from loguru import logger

from .dsl_types import (
    AnimationScript,
    Sequence,
    MobjectDefinition,
    ActionDefinition,
    CreateAction,
    TransformAction,
    IndicateAction,
    MoveAction,
    FadeOutAction,
    VGroupMobject
)


class DSLValidationError(Exception):
    """DSL 验证错误"""

    def __init__(self, message: str, path: Optional[str] = None):
        self.message = message
        self.path = path
        super().__init__(f"[{path}] {message}" if path else message)


class DSLValidator:
    """
    DSL 验证器

    执行以下验证:
    1. 对象ID唯一性检查
    2. 引用完整性检查（动作引用的对象必须已定义）
    3. 时序合理性检查（对象在被引用前必须已创建）
    4. 样式一致性检查
    """

    def __init__(self):
        self.errors: List[DSLValidationError] = []
        self.warnings: List[str] = []

    def validate(self, script: AnimationScript) -> Tuple[bool, List[str], List[str]]:
        """
        验证动画脚本

        Args:
            script: 动画脚本对象

        Returns:
            (is_valid, errors, warnings)
        """
        self.errors = []
        self.warnings = []

        try:
            # 1. 收集所有对象ID
            all_mobject_ids = self._collect_all_mobject_ids(script)

            # 2. 检查ID唯一性
            self._check_id_uniqueness(script)

            # 3. 检查引用完整性
            self._check_reference_integrity(script, all_mobject_ids)

            # 4. 检查时序合理性
            self._check_temporal_order(script)

            # 5. 检查VGroup引用
            self._check_vgroup_references(script, all_mobject_ids)

        except Exception as e:
            logger.exception("DSL 验证过程发生异常")
            self.errors.append(DSLValidationError(f"验证异常: {str(e)}"))

        error_messages = [str(e) for e in self.errors]
        is_valid = len(self.errors) == 0

        return is_valid, error_messages, self.warnings

    def _collect_all_mobject_ids(self, script: AnimationScript) -> Set[str]:
        """收集所有定义的对象ID"""
        ids = set()

        # 全局对象
        for mobject in script.global_mobjects:
            ids.add(mobject.id)

        # 序列中的对象
        for seq in script.sequences:
            for mobject in seq.mobjects:
                ids.add(mobject.id)

        return ids

    def _check_id_uniqueness(self, script: AnimationScript) -> None:
        """检查对象ID唯一性"""
        seen_ids: Dict[str, str] = {}  # id -> location

        # 全局对象
        for mobject in script.global_mobjects:
            if mobject.id in seen_ids:
                self.errors.append(DSLValidationError(
                    f"重复的对象ID: '{mobject.id}'，之前定义于 {seen_ids[mobject.id]}",
                    "global_mobjects"
                ))
            else:
                seen_ids[mobject.id] = "global_mobjects"

        # 序列中的对象
        for seq in script.sequences:
            for mobject in seq.mobjects:
                if mobject.id in seen_ids:
                    self.errors.append(DSLValidationError(
                        f"重复的对象ID: '{mobject.id}'，之前定义于 {seen_ids[mobject.id]}",
                        f"sequences.{seq.id}"
                    ))
                else:
                    seen_ids[mobject.id] = f"sequences.{seq.id}"

    def _check_reference_integrity(
        self, 
        script: AnimationScript, 
        all_ids: Set[str]
    ) -> None:
        """检查引用完整性"""
        for seq in script.sequences:
            for action in seq.actions:
                self._check_action_references(action, all_ids, f"sequences.{seq.id}")

    def _check_action_references(
        self, 
        action: ActionDefinition, 
        all_ids: Set[str],
        path: str
    ) -> None:
        """检查单个动作的引用"""
        if isinstance(action, CreateAction):
            if action.target_id not in all_ids:
                self.errors.append(DSLValidationError(
                    f"CreateAction 引用了未定义的对象: '{action.target_id}'",
                    path
                ))

        elif isinstance(action, TransformAction):
            if action.source_id not in all_ids:
                self.errors.append(DSLValidationError(
                    f"TransformAction 源对象未定义: '{action.source_id}'",
                    path
                ))
            if action.target_id not in all_ids:
                self.errors.append(DSLValidationError(
                    f"TransformAction 目标对象未定义: '{action.target_id}'",
                    path
                ))

        elif isinstance(action, IndicateAction):
            if action.target_id not in all_ids:
                self.errors.append(DSLValidationError(
                    f"IndicateAction 引用了未定义的对象: '{action.target_id}'",
                    path
                ))

        elif isinstance(action, MoveAction):
            if action.target_id not in all_ids:
                self.errors.append(DSLValidationError(
                    f"MoveAction 引用了未定义的对象: '{action.target_id}'",
                    path
                ))
            # 检查相对位置引用
            if action.to_position and action.to_position.relative_to:
                if action.to_position.relative_to not in all_ids:
                    self.errors.append(DSLValidationError(
                        f"MoveAction 位置引用了未定义的对象: '{action.to_position.relative_to}'",
                        path
                    ))

        elif isinstance(action, FadeOutAction):
            for target_id in action.target_ids:
                if target_id not in all_ids:
                    self.errors.append(DSLValidationError(
                        f"FadeOutAction 引用了未定义的对象: '{target_id}'",
                        path
                    ))

    def _check_temporal_order(self, script: AnimationScript) -> None:
        """检查时序合理性：对象必须在被使用前创建"""
        # 已在场景中的对象（已创建/添加）
        active_ids: Set[str] = set()

        # 全局对象默认已存在
        for mobject in script.global_mobjects:
            active_ids.add(mobject.id)

        for seq in script.sequences:
            # 序列开始时，该序列定义的对象变为可用
            # 但只有通过 CreateAction 创建后才真正"激活"
            defined_in_seq = {m.id for m in seq.mobjects}

            for action in seq.actions:
                if isinstance(action, CreateAction):
                    # 创建动作使对象激活
                    if action.target_id in defined_in_seq:
                        active_ids.add(action.target_id)
                    elif action.target_id not in active_ids:
                        self.warnings.append(
                            f"[sequences.{seq.id}] CreateAction 尝试创建未在当前或之前序列定义的对象: '{action.target_id}'"
                        )

                elif isinstance(action, (IndicateAction, MoveAction)):
                    if action.target_id not in active_ids:
                        self.warnings.append(
                            f"[sequences.{seq.id}] 动作引用了尚未在场景中显示的对象: '{action.target_id}'"
                        )

                elif isinstance(action, FadeOutAction):
                    for target_id in action.target_ids:
                        if target_id not in active_ids:
                            self.warnings.append(
                                f"[sequences.{seq.id}] FadeOut 引用了不在场景中的对象: '{target_id}'"
                            )
                        else:
                            # 淡出后对象不再活跃
                            active_ids.discard(target_id)

    def _check_vgroup_references(
        self, 
        script: AnimationScript, 
        all_ids: Set[str]
    ) -> None:
        """检查 VGroup 的子对象引用"""
        for mobject in script.global_mobjects:
            if isinstance(mobject, VGroupMobject):
                for child_id in mobject.children_ids:
                    if child_id not in all_ids:
                        self.errors.append(DSLValidationError(
                            f"VGroup '{mobject.id}' 引用了未定义的子对象: '{child_id}'",
                            "global_mobjects"
                        ))

        for seq in script.sequences:
            for mobject in seq.mobjects:
                if isinstance(mobject, VGroupMobject):
                    for child_id in mobject.children_ids:
                        if child_id not in all_ids:
                            self.errors.append(DSLValidationError(
                                f"VGroup '{mobject.id}' 引用了未定义的子对象: '{child_id}'",
                                f"sequences.{seq.id}"
                            ))


def validate_animation_script(script: AnimationScript) -> bool:
    """
    验证动画脚本的便捷函数

    Args:
        script: 动画脚本对象

    Returns:
        是否验证通过

    Raises:
        DSLValidationError: 验证失败时抛出
    """
    validator = DSLValidator()
    is_valid, errors, warnings = validator.validate(script)

    # 输出警告
    for warning in warnings:
        logger.warning(f"DSL 验证警告: {warning}")

    # 输出错误
    if not is_valid:
        for error in errors:
            logger.error(f"DSL 验证错误: {error}")
        raise DSLValidationError(f"DSL 验证失败，共 {len(errors)} 个错误")

    logger.info("DSL 验证通过")
    return True


if __name__ == "__main__":
    # 测试验证器
    from .dsl_types import (
        AnimationScript, 
        Sequence, 
        TextMobject, 
        MathTexMobject,
        CreateAction, 
        TransformAction,
        WaitAction,
        Position, 
        PositionAnchor,
        AnimationType
    )

    # 创建一个有效的脚本
    valid_script = AnimationScript(
        scene_name="TestScene",
        sequences=[
            Sequence(
                id="intro",
                mobjects=[
                    TextMobject(
                        id="title",
                        content="测试标题",
                        position=Position(edge=PositionAnchor.UP)
                    ),
                    MathTexMobject(
                        id="formula",
                        latex="E=mc^2"
                    )
                ],
                actions=[
                    CreateAction(target_id="title", animation=AnimationType.WRITE),
                    WaitAction(duration=0.5),
                    CreateAction(target_id="formula", animation=AnimationType.WRITE)
                ]
            )
        ]
    )

    validator = DSLValidator()
    is_valid, errors, warnings = validator.validate(valid_script)
    print(f"有效脚本验证: {is_valid}")
    print(f"错误: {errors}")
    print(f"警告: {warnings}")

    # 创建一个无效的脚本（引用不存在的对象）
    invalid_script = AnimationScript(
        scene_name="InvalidScene",
        sequences=[
            Sequence(
                id="intro",
                mobjects=[
                    TextMobject(id="title", content="标题")
                ],
                actions=[
                    CreateAction(target_id="non_existent")  # 错误：引用不存在的对象
                ]
            )
        ]
    )

    is_valid, errors, warnings = validator.validate(invalid_script)
    print(f"\n无效脚本验证: {is_valid}")
    print(f"错误: {errors}")

# -*- coding: utf-8 -*-
"""
Text2Manim Animator Prompts 模块

Layer 2: 动画序列规划
将教学大纲转换为动画 DSL 脚本。

使用 Chain-of-Thought (COT) 提示技术，确保:
1. 准确理解教学步骤
2. 设计合理的动画序列
3. 输出符合 DSL Schema 的 JSON

Author: Text2Manim Team
Date: 2024-12
"""

from typing import Dict, Any, List
import json

# =============================================================================
# DSL 参考文档
# =============================================================================

DSL_REFERENCE = """
## DSL 对象类型 (mobject types)

### 文本类
- `text`: 普通文本 - {"id": "xxx", "type": "text", "content": "文字内容"}
- `math_tex`: 数学公式 - {"id": "xxx", "type": "math_tex", "latex": "LaTeX公式"}

### 几何类
- `dot`: 点 - {"id": "xxx", "type": "dot", "position": {...}}
- `line`: 线段 - {"id": "xxx", "type": "line", "start": [x1, y1], "end": [x2, y2]}
- `arrow`: 箭头 - {"id": "xxx", "type": "arrow", "start": [x1, y1], "end": [x2, y2]}
- `circle`: 圆 - {"id": "xxx", "type": "circle", "radius": 1.0}
- `rectangle`: 矩形 - {"id": "xxx", "type": "rectangle", "width": 2, "height": 1}
- `square`: 正方形 - {"id": "xxx", "type": "square", "side_length": 1}
- `polygon`: 多边形 - {"id": "xxx", "type": "polygon", "vertices": [[x1,y1], [x2,y2], ...]}
- `triangle`: 三角形 - {"id": "xxx", "type": "triangle", "vertices": [[x1,y1], [x2,y2], [x3,y3]]}
- `right_angle`: 直角标记 - {"id": "xxx", "type": "right_angle", "vertex": [x,y], "line1_point": [x1,y1], "line2_point": [x2,y2]}

### 标注类
- `brace`: 大括号 - {"id": "xxx", "type": "brace", "target_id": "目标对象ID", "direction": "down"}
- `surrounding_rectangle`: 包围框 - {"id": "xxx", "type": "surrounding_rectangle", "target_id": "目标对象ID"}

### 坐标系类
- `axes`: 坐标轴 - {"id": "xxx", "type": "axes", "x_range": [-5, 5, 1], "y_range": [-3, 3, 1]}
- `function_graph`: 函数图 - {"id": "xxx", "type": "function_graph", "function_expr": "lambda x: x**2", "axes_id": "坐标轴ID"}

### 组合类
- `vgroup`: 对象组 - {"id": "xxx", "type": "vgroup", "children_ids": ["id1", "id2"]}

## 位置定义 (position)

三种定位方式:
1. 绝对坐标: {"x": 1.0, "y": 2.0}
2. 边缘对齐: {"edge": "up"} 可选值: up/down/left/right/center
3. 相对定位: {"relative_to": "对象ID", "direction": "down", "buff": 0.5}

## 动作类型 (action types)

### 创建动作
{"type": "create", "target_id": "对象ID", "animation": "write/create/fade_in", "run_time": 1.0}
- animation 可选: create, write, fade_in, draw_border, grow_from_center

### 变换动作
{"type": "transform", "source_id": "源对象ID", "target_id": "目标对象ID", "animation": "transform/replacement_transform", "run_time": 1.0}

### 强调动作
{"type": "indicate", "target_id": "对象ID", "animation": "indicate/circumscribe/flash", "run_time": 1.0}

### 移动动作
{"type": "move", "target_id": "对象ID", "shift": [dx, dy], "run_time": 1.0}
或
{"type": "move", "target_id": "对象ID", "to_position": {"edge": "up"}, "run_time": 1.0}

### 淡出动作
{"type": "fade_out", "target_ids": ["id1", "id2"], "run_time": 1.0}

### 等待动作
{"type": "wait", "duration": 1.0}

### 组合动作(同时执行)
{"type": "group", "actions": [动作1, 动作2], "run_time": 1.0}

### 序列动作(依次执行)
{"type": "sequence", "actions": [动作1, 动作2], "lag_ratio": 0.2}
"""

# =============================================================================
# 系统提示词
# =============================================================================

ANIMATOR_SYSTEM_PROMPT = f"""你是一位专业的动画脚本设计师，专门将数学教学大纲转换为 Manim 动画 DSL 脚本。

## 你的专业能力

1. **精通 Manim 动画原理**: 熟悉各类对象和动画的使用方式
2. **教学动画设计经验**: 知道如何通过动画增强教学效果
3. **时间节奏控制**: 能够合理安排动画时长和节奏
4. **布局与构图**: 善于设计清晰美观的画面布局

## DSL 参考
{DSL_REFERENCE}

## 输出格式要求

你必须输出一个严格的 JSON 对象，格式如下:

```json
{{
  "scene_name": "场景类名",
  "title": "动画标题",
  "description": "动画描述",
  "quality": "medium",
  "background_color": "BLACK",
  "global_mobjects": [
    // 全局对象定义
  ],
  "sequences": [
    {{
      "id": "序列ID",
      "name": "序列名称",
      "narration": "旁白/解说",
      "mobjects": [
        // 该序列中创建的对象
      ],
      "actions": [
        // 动画动作序列
      ]
    }}
  ]
}}
```

## 设计原则

1. **对象先定义再使用**: 在 mobjects 中定义后才能在 actions 中引用
2. **ID 全局唯一**: 每个对象的 ID 必须唯一
3. **布局先行**: 先定义位置，再播放动画
4. **节奏合理**: 复杂内容慢一些，简单内容快一些
5. **强调重点**: 关键内容用 indicate 或 surrounding_rectangle 强调

## 常用布局参考

- 标题通常放在上方: position.edge = "up"
- 主要内容在中央: position 不设置或 edge = "center"
- 公式推导纵向排列: 使用 relative_to 和 direction = "down"
- 并排展示: 使用 x 坐标或 direction = "left"/"right"

## Manim 坐标系

- 屏幕中心是原点 (0, 0)
- X轴: 左侧约 -7，右侧约 +7
- Y轴: 下方约 -4，上方约 +4
- 常用方向: UP=[0,1], DOWN=[0,-1], LEFT=[-1,0], RIGHT=[1,0]"""


# =============================================================================
# 用户提示词模板 (带 COT)
# =============================================================================

ANIMATOR_USER_PROMPT_TEMPLATE = """请将以下教学大纲转换为动画 DSL 脚本:

## 教学大纲
```json
{outline_json}
```

## 请按以下步骤思考 (Chain of Thought)

### Step 1: 场景规划
分析教学大纲:
- 一共有几个教学步骤?
- 每个步骤需要什么视觉元素?
- 步骤之间如何过渡?

### Step 2: 对象设计
为每个视觉元素设计 DSL 对象:
- 使用什么类型的 mobject?
- 位置如何安排?
- 样式如何设置?

### Step 3: 动画编排
为每个对象设计动画:
- 用什么方式出现? (create/write/fade_in)
- 需要强调吗? (indicate/circumscribe)
- 需要变换吗? (transform)
- 何时消失? (fade_out)

### Step 4: 时间控制
规划动画时长:
- 每个动画多长时间?
- 需要多少等待时间让观众消化?
- 总时长是否合理?

## 重要约束

1. **对象 ID 必须唯一且有意义**: 如 "title", "triangle", "formula_1"
2. **先定义后使用**: mobjects 中定义的对象才能在 actions 中使用
3. **位置要合理**: 不要让元素重叠或超出屏幕
4. **时长要充足**: 给观众足够的阅读和理解时间

## 输出要求
完成思考后，输出严格的 JSON 格式动画脚本。
只输出 JSON，不要有其他文字。

```json"""


