            "background_color": {"type": "string"},
            "global_mobjects": {"type": "array"},
            "sequences": {
                "type": "array",
                "items": {
                    "type": "object",
                    "required": ["id", "mobjects", "actions"],
                    "properties": {
                        "id": {"type": "string"},
                        "name": {"type": "string"},
                        "narration": {"type": "string"},
                        "mobjects": {"type": "array"},
                        "actions": {"type": "array"}
                    }
                }
