# -*- coding: utf-8 -*-
"""
Text2Manim MCP Server 模块

提供 MCP (Model Context Protocol) 接口，使 Claude 能够直接调用 text2manim 功能。

支持的工具:
1. generate_animation - 生成数学教学动画
2. preview_outline - 预览教学大纲（不生成视频）
3. preview_dsl - 预览动画 DSL 脚本
4. list_examples - 列出示例主题

Author: Text2Manim Team
Date: 2024-12
"""

import os
import sys
import json
import asyncio
from pathlib import Path
from typing import Any, Sequence

from mcp.server import Server
from mcp.server.stdio import stdio_server
from mcp.types import (
    Tool,
    TextContent,
    ImageContent,
    EmbeddedResource,
)


# =============================================================================
# MCP Server 实例
# =============================================================================

server = Server("text2manim-mcp")


# =============================================================================
# 工具定义
# =============================================================================

@server.list_tools()
async def list_tools() -> list[Tool]:
    """列出所有可用工具"""
    return [
        Tool(
            name="generate_animation",
            description="""生成数学教学动画视频。

输入一个数学主题（如"勾股定理的证明"、"二次函数图像"），
系统将自动生成教学大纲、动画脚本和 Manim 视频。

注意事项:
- 生成过程可能需要 1-3 分钟
- 输出为 MP4 视频文件
- 支持中文主题

示例主题:
- 勾股定理的证明
- 圆的面积公式推导
- 二次函数的图像性质
- 三角函数的诱导公式""",
            inputSchema={
                "type": "object",
                "properties": {
                    "topic": {
                        "type": "string",
                        "description": "数学主题，如'勾股定理的证明'"
                    },
                    "quality": {
                        "type": "string",
                        "enum": ["low", "medium", "high"],
                        "default": "medium",
                        "description": "视频质量: low(480p), medium(720p), high(1080p)"
                    },
                    "output_dir": {
                        "type": "string",
                        "default": "output",
                        "description": "输出目录路径"
                    }
                },
                "required": ["topic"]
            }
        ),
        Tool(
            name="preview_outline",
            description="""预览教学大纲，不生成视频。

快速查看系统为主题生成的教学大纲结构，
包括教学步骤、时间规划和视觉元素。

适用于:
- 在生成视频前预览内容
- 调整教学设计
- 了解系统能力""",
            inputSchema={
                "type": "object",
                "properties": {
                    "topic": {
                        "type": "string",
                        "description": "数学主题"
                    }
                },
                "required": ["topic"]
            }
        ),
        Tool(
