async def handle_generate_animation(arguments: dict) -> list[TextContent]:
    """处理动画生成请求"""
    topic = arguments.get("topic", "")
    quality = arguments.get("quality", "medium")
    output_dir = arguments.get("output_dir", "output")

    if not topic:
        return [TextContent(
            type="text",
            text="错误: 请提供数学主题 (topic)"
        )]

    try:
        # 设置环境变量
        os.environ["MANIM_QUALITY"] = quality
        os.environ["MANIM_OUTPUT_DIR"] = output_dir

        # 延迟导入，避免启动时加载过多模块
        from text2manim.pipeline import generate_animation

        # 在线程池中运行同步函数（因为 LLM 调用可能很慢）
        loop = asyncio.get_event_loop()
        result = await loop.run_in_executor(
            None,
            generate_animation,
            topic
        )

        # 构建响应
        if result.success:
            response_text = f"""✅ 动画生成成功!

📋 主题: {topic}
📁 输出文件: {result.output_file}
⏱️ 总耗时: {result.total_time:.2f} 秒
📊 执行步骤: {' → '.join(result.steps_executed)}

教学大纲摘要:
{_format_outline_summary(result.teaching_outline)}
"""
        else:
            response_text = f"""❌ 动画生成失败

📋 主题: {topic}
❗ 错误信息: {result.error_message}
📊 执行步骤: {' → '.join(result.steps_executed)}
"""

        return [TextContent(type="text", text=response_text)]

    except Exception as e:
        return [TextContent(
            type="text",
            text=f"❌ 生成过程出错: {str(e)}"
        )]


async def handle_preview_outline(arguments: dict) -> list[TextContent]:
    """处理大纲预览请求"""
    topic = arguments.get("topic", "")

    if not topic:
        return [TextContent(
            type="text",
