        )]

    try:
        from text2manim.pipeline.nodes import planner_node
        from text2manim.pipeline.state import create_initial_state

        # 创建初始状态
        state = create_initial_state(topic)

        # 运行 planner 节点
        loop = asyncio.get_event_loop()
        result = await loop.run_in_executor(
