async def handle_preview_dsl(arguments: dict) -> list[TextContent]:
    """处理 DSL 预览请求"""
    topic = arguments.get("topic", "")

    if not topic:
        return [TextContent(
            type="text",
            text="错误: 请提供数学主题 (topic)"
        )]

    try:
        from text2manim.pipeline.nodes import planner_node, animator_node
        from text2manim.pipeline.state import create_initial_state

        # 创建初始状态
        state = create_initial_state(topic)

        # 运行 planner 节点
        loop = asyncio.get_event_loop()
        planner_result = await loop.run_in_executor(
            None,
            planner_node,
            state
        )

        if "error_message" in planner_result and planner_result.get("error_message"):
            return [TextContent(
                type="text",
                text=f"❌ 大纲生成失败: {planner_result['error_message']}"
            )]

        # 更新状态
        state.update(planner_result)

        # 运行 animator 节点
        animator_result = await loop.run_in_executor(
            None,
            animator_node,
            state
        )

        if "error_message" in animator_result and animator_result.get("error_message"):
            return [TextContent(
                type="text",
                text=f"❌ DSL 生成失败: {animator_result['error_message']}"
            )]

        script = animator_result.get("animation_script")
        if script:
            # 转换为字典
            if hasattr(script, 'model_dump'):
                script_dict = script.model_dump()
            else:
                script_dict = script

            formatted = json.dumps(script_dict, ensure_ascii=False, indent=2)
            return [TextContent(
                type="text",
                text=f"""🎬 动画 DSL 脚本预览

主题: {topic}

```json
{formatted}
```
"""
            )]
        else:
            return [TextContent(
                type="text",
                text="❌ 未能生成动画脚本"
            )]

    except Exception as e:
        return [TextContent(
            type="text",
            text=f"❌ 预览出错: {str(e)}"
        )]


