async def handle_check_environment(arguments: dict) -> list[TextContent]:
    """检查运行环境"""
    checks = []

    # 检查 Python 版本
    py_version = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
    checks.append(f"✅ Python 版本: {py_version}")

    # 检查 manim
    try:
        import manim
        checks.append(f"✅ Manim 版本: {manim.__version__}")
    except ImportError:
        checks.append("❌ Manim 未安装")

    # 检查 langchain/langgraph
    try:
        import langgraph
        checks.append("✅ LangGraph 已安装")
    except ImportError:
        checks.append("❌ LangGraph 未安装")

    # 检查 OpenAI API Key
    api_key = os.environ.get("OPENAI_API_KEY", "")
    if api_key:
        checks.append(f"✅ OpenAI API Key 已配置 (***{api_key[-4:]})")
    else:
        checks.append("❌ OpenAI API Key 未配置")

    # 检查 LaTeX
    try:
        import subprocess
        result = subprocess.run(["pdflatex", "--version"], capture_output=True, timeout=5)
        if result.returncode == 0:
            checks.append("✅ LaTeX (pdflatex) 已安装")
        else:
            checks.append("⚠️ LaTeX 可能未正确安装")
    except Exception:
        checks.append("⚠️ 无法检查 LaTeX 安装状态")

    # 检查 ffmpeg
    try:
        import subprocess
        result = subprocess.run(["ffmpeg", "-version"], capture_output=True, timeout=5)
        if result.returncode == 0:
            checks.append("✅ FFmpeg 已安装")
        else:
            checks.append("⚠️ FFmpeg 可能未正确安装")
    except Exception:
        checks.append("⚠️ 无法检查 FFmpeg 安装状态")

    response = "🔍 环境检查结果\n\n" + "\n".join(checks)

    return [TextContent(type="text", text=response)]


