def _format_outline_summary(outline: dict | None) -> str:
    """格式化大纲摘要"""
    if not outline:
        return "无"

    if hasattr(outline, 'model_dump'):
        outline = outline.model_dump()

    topic = outline.get("topic", "未知")
    subject = outline.get("subject_area", "未知")
    steps = outline.get("steps", [])
    duration = outline.get("estimated_duration", 0)

    step_summary = "\n".join([
        f"  {i+1}. [{s.get('type', '')}] {s.get('title', '')}"
        for i, s in enumerate(steps)
    ])

    return f"""  主题: {topic}
  学科: {subject}
  步骤数: {len(steps)}
  预计时长: {duration}秒

  步骤列表:
{step_summary}"""


