async def handle_generate_animation(arguments: dict) -> list[TextContent]:
    """处理动画生成请求"""
    topic = arguments.get("topic", "")
    quality = arguments.get("quality", "medium")
    output_dir = arguments.get("output_dir", "output")
    use_react = arguments.get("use_react", False)
    max_iterations = arguments.get("max_iterations", 10)

    if not topic:
        return [TextContent(
            type="text",
            text="错误: 请提供数学主题 (topic)"
        )]

    try:
        # 设置环境变量
        os.environ["MANIM_QUALITY"] = quality
        os.environ["MANIM_OUTPUT_DIR"] = output_dir

        # 延迟导入，避免启动时加载过多模块
        from text2manim.pipeline import generate_animation

        # 在线程池中运行同步函数（因为 LLM 调用可能很慢）
        loop = asyncio.get_event_loop()

        # 使用 functools.partial 传递参数
        import functools
        func = functools.partial(
            generate_animation, 
            topic, 
            use_react=use_react,
            max_iterations=max_iterations
        )
        result = await loop.run_in_executor(None, func)

        # 构建响应
        mode_str = "ReAct 智能模式" if use_react else "传统模式"
        if result.success:
            response_text = f"""✅ 动画生成成功! ({mode_str})

📋 主题: {topic}
📁 输出文件: {result.output_file}
⏱️ 总耗时: {result.total_time:.2f} 秒
📊 执行步骤: {' → '.join(result.steps_executed)}
"""
            # 如果是 ReAct 模式，显示推理信息
            if use_react and result.react_iterations > 0:
                response_text += f"""
🧠 ReAct 推理:
  - 迭代次数: {result.react_iterations}/{max_iterations}
  - 推理步数: {result.react_steps}
  - 质量评分: {result.quality_score:.2f if result.quality_score else 'N/A'}
  - LLM 调用: {len(result.llm_records)} 次
"""

            response_text += f"""
教学大纲摘要:
{_format_outline_summary(result.teaching_outline)}
"""
        else:
            response_text = f"""❌ 动画生成失败 ({mode_str})

📋 主题: {topic}
❗ 错误信息: {result.error_message}
📊 执行步骤: {' → '.join(result.steps_executed)}
"""
            if use_react:
                response_text += f"""
🧠 ReAct 状态:
  - 迭代次数: {result.react_iterations}/{max_iterations}
  - 推理步数: {result.react_steps}
"""
                if result.react_thoughts:
                    response_text += "\n📝 最近思考过程:\n"
                    for t in result.react_thoughts[-3:]:  # 显示最后3条
                        response_text += f"  Step {t.get('step')}: [{t.get('action')}] {t.get('thought', '')[:50]}...\n"

        return [TextContent(type="text", text=response_text)]

    except Exception as e:
        return [TextContent(
            type="text",
            text=f"❌ 生成过程出错: {str(e)}"
        )]

